package com.semes.reqops.domain.knowledge.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="KNOWLEDGE_ENTRIES") public class KnowledgeEntry {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="project_id",nullable=false) private Long projectId;@Column(name="source_type",nullable=false,length=30) private String sourceType;@Column(name="source_id",nullable=false) private Long sourceId;@Column(name="source_version_id") private Long sourceVersionId;@Lob @Column(nullable=false) private String content;@Column(name="content_hash",nullable=false,length=64) private String contentHash;@Column(nullable=false) private int active=1;@Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt;protected KnowledgeEntry(){}public KnowledgeEntry(Long p,String type,Long source,Long version,String content,String hash){projectId=p;sourceType=type;sourceId=source;sourceVersionId=version;this.content=content;contentHash=hash;}@PrePersist void created(){createdAt=LocalDateTime.now();}public Long getId(){return id;}public Long getProjectId(){return projectId;}public String getContent(){return content;}public String getContentHash(){return contentHash;}}
